static lstr L3003 = {-1, 1084, "// std/option: helpers over the prelude Option.\012\012export function map<T, U, effect E>(option: Option<T>, f: (value: T) => U uses E): Option<U> uses alloc, E {\012  return match (option) {\012    Some(value) => Some(f(value))\012    None => None\012  }\012}\012\012export function andThen<T, U, effect E>(option: Option<T>, f: (value: T) => Option<U> uses E): Option<U> uses E {\012  return match (option) {\012    Some(value) => f(value)\012    None => None\012  }\012}\012\012export function withDefault<T>(option: Option<T>, fallback: T): T {\012  return match (option) {\012    Some(value) => value\012    None => fallback\012  }\012}\012\012export function orElse<T, effect E>(option: Option<T>, f: () => Option<T> uses E): Option<T> uses E {\012  return match (option) {\012    Some(_) => option\012    None => f()\012  }\012}\012\012export function isSome<T>(option: Option<T>): bool {\012  return option is Some(_)\012}\012\012export function isNone<T>(option: Option<T>): bool {\012  return option is None\012}\012\012export function okOr<T, F>(option: Option<T>, error: F): Result<T, F> uses alloc {\012  return match (option) {\012    Some(value) => Ok(value)\012    None => Err(error)\012  }\012}\012"};
